// scripts/generate-destinations.js — one-off (or periodic) content
// generation for the /destinations/:slug SEO pages. Run manually:
//
//   node scripts/generate-destinations.js            (all curated slugs)
//   node scripts/generate-destinations.js naples rome (just those)
//
// This does NOT run automatically at server start or on each visit —
// content/destinations.json is committed content, regenerated by a human
// (or a scheduled job you set up yourself) when it's worth refreshing.

require('dotenv').config();
const fs = require('fs');
const path = require('path');
const { askClaude, parseJsonLenient } = require('../lib/claude');

const OUT_PATH = path.join(__dirname, '..', 'content', 'destinations.json');

// Curated starter list — real, popular, deliberately varied destinations.
// Add more here and re-run (with just the new slugs as argv to avoid
// re-spending on the ones already generated).
const CURATED = [
  { slug: 'naples', query: 'Le Golfe de Naples, Italie (Naples, Capri, Positano, Pompéi)' },
  { slug: 'calanques', query: 'Les Calanques, près de Marseille, France' },
  { slug: 'lisbonne', query: 'Lisbonne, Portugal' },
  { slug: 'santorin', query: 'Santorin, Grèce' }
];

const tierSchema =
  '{"key":"low","label":"Essentiel","hotel":{"name":"...","pricePerNight":0},"activities":["...","...","..."],"restaurants":[{"name":"...","address":"..."},{"name":"...","address":"..."}],"estimatedTotal":0},' +
  '{"key":"mid","label":"Confort","hotel":{"name":"...","pricePerNight":0},"activities":["...","...","...","..."],"restaurants":[{"name":"...","address":"..."},{"name":"...","address":"..."},{"name":"...","address":"..."}],"estimatedTotal":0},' +
  '{"key":"high","label":"Signature","hotel":{"name":"...","pricePerNight":0},"activities":["...","...","...","...","...","..."],"restaurants":[{"name":"...","address":"..."},{"name":"...","address":"..."},{"name":"...","address":"..."},{"name":"...","address":"..."}],"estimatedTotal":0}';

function systemPromptFor() {
  return 'Tu rédiges le contenu d\'une page de destination pour le site de voyage "Peacetrip". Réponds UNIQUEMENT avec un objet JSON valide, sans texte avant ni après, sans balises markdown. Schéma exact :\n' +
    '{"name":"Nom usuel de la destination","country":"Pays","tagline":"Phrase courte et évocatrice (8-12 mots)","description":["Paragraphe 1 (40-60 mots)","Paragraphe 2 (40-60 mots)"],"metaDescription":"Résumé neutre pour Google, 140-155 caractères maximum","tiers":[' + tierSchema + ']}\n' +
    'Le "tagline" et la "description" doivent donner envie sans être ronflants, rester factuels (pas de superlatifs vagues type "incontournable"), et refléter le vrai caractère du lieu. "metaDescription" est un résumé neutre destiné à un moteur de recherche, pas une accroche marketing. Les 3 formules (tiers) sont pour 6 nuits et 2 voyageurs, prix en euros incluant vols + hôtel + activités. Le niveau Essentiel doit être nettement moins cher que Signature. Reste concis : chaque activité/restaurant tient en 2-5 mots, chaque adresse en une ligne courte. N\'utilise JAMAIS de guillemets doubles (") à l\'intérieur d\'un texte.';
}

async function generateOne(target) {
  const systemPrompt = systemPromptFor();
  const userMsg = `Destination : ${target.query}.`;
  const clean = await askClaude(systemPrompt, userMsg, 2200);
  const parsed = parseJsonLenient(clean);
  if (!parsed.name || !parsed.tiers || parsed.tiers.length < 3) throw new Error('Réponse incomplète pour ' + target.slug);
  return { slug: target.slug, ...parsed, generatedAt: new Date().toISOString() };
}

async function main() {
  const requested = process.argv.slice(2);
  const targets = requested.length ? CURATED.filter(d => requested.includes(d.slug)) : CURATED;
  if (!targets.length) {
    console.error('Aucun slug reconnu parmi :', requested.join(', '));
    console.error('Slugs disponibles :', CURATED.map(d => d.slug).join(', '));
    process.exit(1);
  }

  let existing = {};
  if (fs.existsSync(OUT_PATH)) {
    try { existing = JSON.parse(fs.readFileSync(OUT_PATH, 'utf8')); } catch (_e) { /* start fresh */ }
  }

  for (const target of targets) {
    process.stdout.write(`Génération : ${target.slug}... `);
    try {
      const data = await generateOne(target);
      existing[target.slug] = data;
      console.log('OK —', data.name);
    } catch (err) {
      console.log('ÉCHEC —', err.message);
    }
  }

  fs.mkdirSync(path.dirname(OUT_PATH), { recursive: true });
  fs.writeFileSync(OUT_PATH, JSON.stringify(existing, null, 2) + '\n');
  console.log(`\n${Object.keys(existing).length} destination(s) dans ${OUT_PATH}`);
}

main().catch(err => { console.error(err); process.exit(1); });
